INSERT INTO public.persian_quotes (text_persian, text_english, poet, poet_english, source, category, tags) VALUES
('بی‌کمالی‌های انسان از سخن پیدا شود / پسته بی‌مغز چون لب وا کند رسوا شود', 'Human imperfections are revealed through speech / A brainless pistachio is disgraced when it opens its lips', 'صائب تبریزی', 'Saib Tabrizi', 'دیوان اشعار', 'حکمت', ARRAY['حکمت']),
('آب زنید راه را هین که نگار می‌رسد / مژده دهید باغ را بوی بهار می‌رسد', 'Sprinkle water on the path, behold the beloved arrives / Give good tidings to the garden, the scent of spring arrives', 'مولانا جلال‌الدین رومی', 'Rumi', 'دیوان اشعار', 'امید', ARRAY['امید']),
('بوی جوی مولیان آید همی / یاد یار مهربان آید همی', 'The scent of the Muliyan stream is coming / The memory of the kind friend is coming', 'رودکی', 'Rudaki', 'دیوان اشعار', 'دوستی', ARRAY['دوستی']),
('ای دیو سپید پای در بند / ای گنبد گیتی ای دماوند', 'O bound white demon / O dome of the world, O Damavand', 'ملک‌الشعرای بهار', 'Mohammad-Taqi Bahar', 'دیوان اشعار', 'طبیعت', ARRAY['طبیعت']),
('به سراغ من اگر می‌آیید، نرم و آهسته بیایید، مبادا که ترک بردارد چینی نازک تنهایی من', 'If you come to me, come softly and slowly, lest the fragile porcelain of my loneliness cracks', 'سهراب سپهری', 'Sohrab Sepehri', 'دیوان اشعار', 'غم و شادی', ARRAY['غم و شادی']),
('من اینجا ریشه در خاکم / من اینجا عاشق این خاک اگر آلوده یا پاکم', 'I am rooted in the soil here / I am in love with this soil here, whether polluted or pure', 'فریدون مشیری', 'Fereydoon Moshiri', 'دیوان اشعار', 'وطن', ARRAY['وطن']),
('ای عشق همه بهانه از توست / من خامشم این ترانه از توست', 'O love, all excuses are from you / I am silent, this song is from you', 'هوشنگ ابتهاج', 'Hushang Ebtehaj', 'دیوان اشعار', 'عشق', ARRAY['عشق']),
('درد عشقی کشیده‌ام که مپرس / زهر هجری چشیده‌ام که مپرس', 'I have suffered a pain of love that you should not ask / I have tasted a poison of separation that you should not ask', 'حافظ شیرازی', 'Hafez', 'دیوان اشعار', 'عشق', ARRAY['عشق']),
('آنچه شیران را کند روبه مزاج / احتیاج است احتیاج است احتیاج', 'That which makes lions have the temperament of foxes / Is need, is need, is need', 'امیرخسرو دهلوی', 'Amir Khusrau', 'دیوان اشعار', 'حکمت', ARRAY['حکمت']),
('دریای خروشان منم، این موج ز من نیست / من قطره‌ام و این همه طوفان ز من است', 'I am a roaring sea, this wave is not from me / I am a drop and all this storm is from me', 'خاقانی شروانی', 'Khaqani', 'دیوان اشعار', 'عرفان', ARRAY['عرفان']),
('ما در پیاله عکس رخ یار دیده‌ایم / ای بی‌خبر ز لذت شرب مدام ما', 'We have seen the reflection of the beloved''s face in the cup / O ignorant one of the pleasure of our constant drinking', 'حافظ شیرازی', 'Hafez', 'دیوان اشعار', 'عرفان', ARRAY['عرفان']),
('آمدی جانم به قربانت ولی حالا چرا / بی‌وفا حالا که من افتاده‌ام از پا چرا', 'You came, my soul be sacrificed for you, but why now / Faithless, now that I have fallen, why', 'شهریار', 'Shahriar', 'دیوان اشعار', 'غم و شادی', ARRAY['غم و شادی']),
('قاصدک! هان، چه خبر آوردی؟ / از کجا وز که خبر آوردی؟', 'Dandelion! Behold, what news did you bring? / From where and from whom did you bring news?', 'مهدی اخوان ثالث', 'Mehdi Akhavan-Sales', 'دیوان اشعار', 'امید', ARRAY['امید']),
('نه تو می‌مانی و نه اندوه / و نه هیچیک از مردم این آبادی...', 'Neither you remain, nor sorrow / Nor any of the people of this village...', 'سهراب سپهری', 'Sohrab Sepehri', 'دیوان اشعار', 'زمان', ARRAY['زمان']),
('پرواز را به خاطر بسپار / پرنده مردنی است', 'Remember the flight / The bird is mortal', 'فروغ فرخزاد', 'Forough Farrokhzad', 'دیوان اشعار', 'زندگی', ARRAY['زندگی']),
('مرگ من روزی فرا خواهد رسید / در بهاری روشن از امواج نور', 'My death will arrive one day / In a spring bright with waves of light', 'فروغ فرخزاد', 'Forough Farrokhzad', 'دیوان اشعار', 'زندگی', ARRAY['زندگی']),
('روزی که برف سرخ ببارد از آسمان / بخت سیاه اهل هنر سبز می‌شود', 'The day red snow falls from the sky / The black fortune of the people of art becomes green', 'صائب تبریزی', 'Saib Tabrizi', 'دیوان اشعار', 'هنر', ARRAY['هنر']),
('بیستون را عشق کند و شهرتش فرهاد برد / رنج گل بلبل کشید و برگ گل را باد برد', 'Love dug Bisotun and Farhad took the fame / The nightingale bore the pain of the rose and the wind took its petal', 'شهریار', 'Shahriar', 'دیوان اشعار', 'عشق', ARRAY['عشق']),
('ای خدا این وصل را هجران مکن / سرخوشان عشق را نالان مکن', 'O God, do not make this union a separation / Do not make the intoxicated ones of love lament', 'مولانا جلال‌الدین رومی', 'Rumi', 'دیوان اشعار', 'عشق', ARRAY['عشق']),
('چون عهده نمی‌شود کسی فردا را / حالی خوش دار این دل پر سودا را', 'Since no one can guarantee tomorrow / Keep this passionate heart happy for now', 'عمر خیام', 'Omar Khayyam', 'دیوان اشعار', 'زندگی', ARRAY['زندگی']),
